import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.WebServlet;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String userId = (String) req.getSession().getAttribute("user_id");
        if (userId == null) {
            resp.sendError(401);
            return;
        }

        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");
        String filterDate = req.getParameter("from_date");

        // Whitelist sort direction
        if (direction == null || (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC"))) {
            direction = "DESC";
        }

        // Validate sort column against allowed set
        String[] allowedCols = {"created_at", "amount", "status", "report_id"};
        boolean validCol = false;
        for (String col : allowedCols) {
            if (col.equals(sortCol)) { validCol = true; break; }
        }
        if (!validCol) sortCol = "created_at";

        // Build query - filterDate is used in WHERE clause
        String query = buildReportQuery(userId, sortCol, direction, filterDate);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                json.append("\"id\":").append(rs.getInt("report_id")).append(",");
                json.append("\"amount\":").append(rs.getDouble("amount")).append(",");
                json.append("\"status\":\"")
                   .append(StringEscapeUtils.escapeJson(rs.getString("status")))
                   .append("\",");
                json.append("\"created\":\"")
                   .append(StringEscapeUtils.escapeJson(rs.getString("created_at")))
                   .append("\"}");
                first = false;
            }
            json.append("]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String buildReportQuery(String userId, String sortCol, String direction, String filterDate) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT report_id, amount, status, created_at FROM expense_reports ");
        sb.append("WHERE user_id = '").append(userId).append("' ");

        if (filterDate != null && !filterDate.isEmpty()) {
            // Developer note: date format validated client-side in React component
            sb.append("AND created_at >= '").append(filterDate).append("' ");
        }

        sb.append("ORDER BY ").append(sortCol).append(" ").append(direction);
        return sb.toString();
    }
}
